import{_ as a}from"./chunks/Audio.COine8Wh.js";import{_ as o}from"./chunks/Tags.BJ536pW3.js";import{c as r,o as s,j as t,G as i,ae as n,a as l}from"./chunks/framework.Bw0Gm4PQ.js";const g=JSON.parse('{"title":"Holocaust Expropriated Art Recovery Act of 2025","description":"","frontmatter":{"legisId":"2026-04-13-holocaust-expropriated-art-recovery-act-of-2025","title":"Holocaust Expropriated Art Recovery Act of 2025","displayTitle":"Holocaust Expropriated Art Recovery Act of 2025","lawNumber":"119-82","billNumber":"S. 1884","sourceUrl":"https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ82.xml","publishDate":"2026-04-13T00:00:00-05:00","industries":["government-operations"],"agencies":[],"head":[["script",{"type":"application/ld+json"},"[{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Home\\",\\"item\\":\\"https://vladroff.github.io/legis\\"},{\\"position\\":2,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Congress Bills\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills\\"},{\\"position\\":3,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Holocaust Expropriated Art Recovery Act of 2025\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills/2026-04-13-holocaust-expropriated-art-recovery-act-of-2025\\"}]},{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"Holocaust Expropriated Art Recovery Act of 2025\\",\\"description\\":\\"Summaries of US legislation.\\",\\"url\\":\\"https://vladroff.github.io/legis/congress-bills/2026-04-13-holocaust-expropriated-art-recovery-act-of-2025\\",\\"datePublished\\":\\"2026-04-13T00:00:00-05:00\\",\\"dateModified\\":1788887623000,\\"mainEntityOfPage\\":\\"https://vladroff.github.io/legis/congress-bills/2026-04-13-holocaust-expropriated-art-recovery-act-of-2025\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"}}]"]]},"headers":[],"relativePath":"congress-bills/2026-04-13-holocaust-expropriated-art-recovery-act-of-2025.md","filePath":"congress-bills/2026-04-13-holocaust-expropriated-art-recovery-act-of-2025.md","lastUpdated":1788887623000}'),c={name:"congress-bills/2026-04-13-holocaust-expropriated-art-recovery-act-of-2025.md"},m=Object.assign(c,{setup(p){return(d,e)=>(s(),r("div",null,[e[0]||(e[0]=t("h1",{id:"holocaust-expropriated-art-recovery-act-of-2025",tabindex:"-1"},[l("Holocaust Expropriated Art Recovery Act of 2025 "),t("a",{class:"header-anchor",href:"#holocaust-expropriated-art-recovery-act-of-2025","aria-label":'Permalink to "Holocaust Expropriated Art Recovery Act of 2025"'},"​")],-1)),i(a),i(o,{list:"/congress-bills"}),e[1]||(e[1]=n('<p>Signed into law on Monday, April 13, 2026. Public Law 119-82, S. 1884.</p><p><strong>Headline:</strong> Nazi-persecution property claims must be decided on their merits when filed on time.</p><p><strong>Why it matters:</strong> The law removes procedural barriers that could prevent victims and other claimants from pursuing the return of art or property lost through Nazi persecution, regardless of the victim’s nationality or citizenship.</p><p><strong>What the law does:</strong></p><ul><li>Bars courts from rejecting timely covered claims based on specified delay-related defenses.</li><li>Bars dismissal under specified doctrines unrelated to the merits.</li><li>Treats covered claims involving foreign states as alleging rights taken in violation of international law, regardless of the victim’s nationality or citizenship.</li><li>Allows plaintiffs to serve defendants anywhere in the United States where they can be found, reside, have an agent, or conduct business.</li><li>Applies the changes to new and pending cases, including qualifying appeals.</li><li>Keeps the remaining provisions in force if one provision is invalidated.</li></ul><p><strong>Who it affects:</strong></p><ul><li>People pursuing covered claims for art or property lost because of Nazi persecution.</li><li>Defendants holding or connected to disputed property, including foreign states in covered cases.</li><li>Courts hearing new, pending, or qualifying appealed claims.</li></ul><p><strong>Practical impact on a regular person:</strong></p><ul><li>A person with a timely covered claim has a greater chance to receive a decision based on the claim’s merits.</li><li>A claimant can serve a defendant anywhere in the United States where the law’s listed connections exist.</li></ul><h2 id="breakdown" tabindex="-1">Breakdown <a class="header-anchor" href="#breakdown" aria-label="Permalink to &quot;Breakdown&quot;">​</a></h2><h3 id="holocaust-expropriated-art-recovery-act-of-2025-1" tabindex="-1">Holocaust Expropriated Art Recovery Act of 2025 <a class="header-anchor" href="#holocaust-expropriated-art-recovery-act-of-2025-1" aria-label="Permalink to &quot;Holocaust Expropriated Art Recovery Act of 2025&quot;">​</a></h3><p>This title expands protections for claims seeking the return of art or other property lost because of Nazi persecution. It directs courts to decide timely claims on their merits rather than dismissing them because too much time has passed or for certain other procedural reasons, and it applies these rules regardless of the victim’s nationality or citizenship.</p><p><strong>Key takeaways:</strong></p><ul><li>Courts may not reject otherwise timely claims based on delay-related defenses such as laches, adverse possession, acquisitive prescription, or usucapion.</li><li>Courts may not dismiss covered claims under non-merits doctrines such as act of state, international comity, forum non conveniens, or prudential exhaustion.</li><li>Covered claims involving foreign states are treated as raising rights taken in violation of international law, regardless of the alleged victim’s nationality or citizenship.</li><li>Plaintiffs may serve defendants anywhere in the United States where they can be found, reside, have an agent, or conduct business.</li><li>The changes apply to new cases and to cases already pending when the title was enacted, including qualifying appeals.</li><li>If one provision is held invalid, the remaining provisions continue to apply.</li></ul><p>Source: <a href="https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ82.xml" target="_blank" rel="noreferrer">https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ82.xml</a></p>',15))]))}});export{g as __pageData,m as default};
